//! en: Target device DB. Never hand-written: the DB is generated from `ch32-device-data`
//! (geometry / memory map / option splits / DM addresses) and `ch32-data` (device_id), and
//! committed under `generated/` (docs/architecture.ja.md §3). Missing data is requested from
//! ch32-device-data (docs/data-requests/); until delivery, a provisional overlay under
//! `provisional/` fills the gap. Every SKU carries `verified` / `provisional` flags that
//! surface in tool output.
//! The built-in DB is generated by `cargo xtask db-gen` into `generated/skus.csv` and embedded
//! with `include_str!`, so the build never reads a neighbour repo.
//!
//! ja: target device DB。手書きせず、ch32-device-data と ch32-data からの生成物を
//! `generated/` に commit する。不足データは ch32-device-data へ依頼し、納品までは
//! `provisional/` の暫定 overlay で進む。SKU ごとに verified / provisional flag を持ち出力に出す。
//! 内蔵 DB は `cargo xtask db-gen` が `generated/skus.csv` を生成し `include_str!` で埋め込む。

use serde::{Deserialize, Serialize};

/// The embedded generated SKU table (produced by `cargo xtask db-gen`).
const GENERATED_SKUS: &str = include_str!("../generated/skus.csv");

/// The embedded generated per-family USER-byte option fields (produced by `cargo xtask db-gen`).
const GENERATED_OPTION_FIELDS: &str = include_str!("../generated/option_fields.csv");

/// The embedded generated per-series debug-wiring table (produced by `cargo xtask db-gen`).
const GENERATED_DEBUG_WIRING: &str = include_str!("../generated/debug_wiring.csv");

/// The embedded generated per-family flash geometry (produced by `cargo xtask db-gen`).
const GENERATED_FLASH_GEOMETRY: &str = include_str!("../generated/flash_geometry.csv");

/// en: Provenance of the embedded device DB, for `version --json` reproducibility
/// (docs/architecture.ja.md §3). ja: 埋め込み device DB の来歴。`version --json` の再現性表示用。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DbProvenance {
    /// The `ch32-device-data` revision the DB was generated from (from the generated headers).
    /// None if the generated files carry no `# source:` header.
    pub source_rev: Option<String>,
    /// A stable identity fingerprint of the embedded DB bytes (`fnv1a64:<hex>`), in the same
    /// convention as `flash_stub_digest`. Not cryptographic - it just pins what is baked in.
    pub digest: String,
}

/// en: Provenance of the embedded DB: the source `ch32-device-data` rev plus an fnv1a64 fingerprint
/// of the embedded generated bytes. ja: 埋め込み DB の来歴(source rev + 生成バイトの fnv1a64 指紋)。
pub fn provenance() -> DbProvenance {
    // ja: `# source: ch32-device-data@<rev> (...)` ヘッダから rev を取る(全生成物で同一)。
    let source_rev = GENERATED_SKUS
        .lines()
        .find_map(|line| line.trim_start_matches('#').trim().strip_prefix("source:"))
        .and_then(|rest| rest.split('@').nth(1))
        .map(|after_at| {
            after_at
                .split([' ', '(', '\t'])
                .next()
                .unwrap_or(after_at)
                .to_string()
        });

    // FNV-1a 64-bit over every embedded generated file, matching `flash_stub_digest`'s convention.
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for part in [
        GENERATED_SKUS,
        GENERATED_OPTION_FIELDS,
        GENERATED_DEBUG_WIRING,
        GENERATED_FLASH_GEOMETRY,
    ] {
        for &b in part.as_bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x100_0000_01b3);
        }
    }

    DbProvenance {
        source_rev,
        digest: format!("fnv1a64:{h:016x}"),
    }
}

/// en: Flash erase/program granularities for a family (bytes; 0 = not applicable). ja: family の
/// flash 消去/書込粒度(byte、0=非該当)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FlashGeometry {
    /// Standard page erase (the slow PER path).
    pub page_erase: u32,
    /// Fast page erase (FTER) - the granularity `erase --range` / flash breakpoints use.
    pub fast_erase: u32,
    /// Fast program chunk.
    pub fast_program: u32,
    /// Block erase (0 when the family has none).
    pub block_erase: u32,
}

/// en: The flash geometry for a DB `family` string (e.g. `CH32L103`, `CH32V307`). None when the
/// family is not in the DB. ja: DB family の flash geometry。DB に無ければ None。
pub fn flash_geometry(family: &str) -> Option<FlashGeometry> {
    GENERATED_FLASH_GEOMETRY.lines().find_map(|line| {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            return None;
        }
        // family,page_erase,fast_erase,fast_program,block_erase
        let f: Vec<&str> = line.split(',').collect();
        let [fam, page, fast_e, fast_p, block] = f.as_slice() else {
            return None;
        };
        if !fam.eq_ignore_ascii_case(family) {
            return None;
        }
        Some(FlashGeometry {
            page_erase: page.parse().unwrap_or(0),
            fast_erase: fast_e.parse().unwrap_or(0),
            fast_program: fast_p.parse().unwrap_or(0),
            block_erase: block.parse().unwrap_or(0),
        })
    })
}

/// en: The SWD/SWIO debug wiring for a part series. ja: series の debug 配線。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DebugWiring {
    /// `1-wire` (SWIO only), `2-wire` (RVSWD), or `1-or-2-wire` (both supported).
    pub wire: String,
    /// SWDIO / single-wire data pad (e.g. `PA13`, `PD1`).
    pub swdio: String,
    /// SWCLK pad (e.g. `PA14`), or `-` for a 1-wire part.
    pub swclk: String,
}

/// en: The debug wiring for a part `series` string (e.g. `CH32V003`, `CH32L103`). None when the
/// series is not in the DB. ja: series の debug 配線。DB に無ければ None。
pub fn debug_wiring(series: &str) -> Option<DebugWiring> {
    GENERATED_DEBUG_WIRING.lines().find_map(|line| {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            return None;
        }
        // series,wire,swdio,swclk
        let f: Vec<&str> = line.split(',').collect();
        let [s, wire, swdio, swclk] = f.as_slice() else {
            return None;
        };
        if !s.eq_ignore_ascii_case(series) {
            return None;
        }
        Some(DebugWiring {
            wire: (*wire).to_owned(),
            swdio: (*swdio).to_owned(),
            swclk: (*swclk).to_owned(),
        })
    })
}

/// One named single-bit field of the option USER byte, for a family.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OptionUserField {
    /// Bit position within the USER byte.
    pub bit: u8,
    /// Field name from the reference manual (e.g. `IWDGSW`, `STOPRST`, `CFGCANM`).
    pub field: String,
    /// Factory-default value of this bit.
    pub default: u8,
}

/// en: The named USER-byte option-bit fields for a DB `family` string (e.g. `CH32L103`,
/// `CH32V20x`, `CH32V307`), sorted high bit first. Empty when the family is not in the DB.
/// ja: DB の family 文字列に対する USER byte の名前付き option bit 群(高 bit 順)。DB に無ければ空。
pub fn option_user_fields(family: &str) -> Vec<OptionUserField> {
    let mut out: Vec<OptionUserField> = GENERATED_OPTION_FIELDS
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                return None;
            }
            // family,bit,field,default
            let f: Vec<&str> = line.split(',').collect();
            let [fam, bit, field, default] = f.as_slice() else {
                return None;
            };
            if !fam.eq_ignore_ascii_case(family) {
                return None;
            }
            Some(OptionUserField {
                bit: bit.parse().ok()?,
                field: (*field).to_owned(),
                default: default.parse().unwrap_or(0),
            })
        })
        .collect();
    out.sort_by_key(|f| core::cmp::Reverse(f.bit));
    out
}

/// Silicon-revision bits [7:4] of the device_id are don't-care when matching (every delivered row
/// uses this mask; `xtask db-gen` rejects any other).
const DEVICE_ID_MASK: u32 = 0xFFFF_FF0F;

/// en: How a chip_id resolved against the DB. ja: chip_id を DB で解決した結果。
#[derive(Debug, Clone, PartialEq)]
pub enum Resolution<'a> {
    /// Exactly one SKU matched.
    Sku(&'a SkuRecord),
    /// Several SKUs matched but all share a family (SKU ambiguous, family known).
    Family(String, Vec<&'a SkuRecord>),
    /// No SKU matched (unknown / gap-series part).
    Unknown,
}

/// en: The device DB: a read-only view over the generated data plus overlays.
/// ja: device DB。生成物 + overlay をまとめた読み取り専用ビュー。
#[derive(Debug, Default)]
pub struct Db {
    skus: Vec<SkuRecord>,
}

impl Db {
    /// en: Built-in (generated) DB, embedded at compile time from `generated/skus.csv`.
    /// ja: 内蔵(生成済み)DB。`generated/skus.csv` をコンパイル時に埋め込む。
    pub fn builtin() -> Self {
        let mut skus = Vec::new();
        for line in GENERATED_SKUS.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            // sku,family,series,device_id,id_addr,flash_bytes,sram_bytes,verified
            let f: Vec<&str> = line.split(',').collect();
            let [
                sku,
                family,
                series,
                device_id,
                _id_addr,
                flash,
                sram,
                verified,
            ] = f.as_slice()
            else {
                continue;
            };
            let device_id = device_id
                .strip_prefix("0x")
                .and_then(|h| u32::from_str_radix(h, 16).ok());
            skus.push(SkuRecord {
                sku: (*sku).to_owned(),
                family: (*family).to_owned(),
                series: (*series).to_owned(),
                device_id,
                flash_bytes: flash.parse().unwrap_or(0),
                sram_bytes: sram.parse().unwrap_or(0),
                // `verified` = the device_id was confirmed on real silicon by this project; the rest
                // is datasheet/reference data.
                verified: *verified == "true",
                provisional: false,
            });
        }
        Self { skus }
    }

    pub fn skus(&self) -> &[SkuRecord] {
        &self.skus
    }

    /// en: The distinct DB families a `--chip` name could mean (a SKU, a family, a series, or a
    /// part-number prefix), for validating `--chip` against the detected chip. Empty when the name
    /// is not in the DB (e.g. a gap-series part), so callers should not treat empty as a conflict.
    /// ja: `--chip` 名(SKU/family/series/型番 prefix)が指しうる DB family 群。検出との突き合わせ用。
    /// DB に無ければ空(未収載 part 等)なので、空を矛盾扱いしないこと。
    pub fn families_for_chip_name(&self, name: &str) -> Vec<String> {
        let up = name.to_ascii_uppercase();
        let mut fams: Vec<String> = self
            .skus
            .iter()
            .filter(|s| {
                s.sku.eq_ignore_ascii_case(name)
                    || s.family.eq_ignore_ascii_case(name)
                    || s.series.eq_ignore_ascii_case(name)
                    || s.sku.to_ascii_uppercase().starts_with(&up)
            })
            .map(|s| s.family.clone())
            .collect();
        fams.sort();
        fams.dedup();
        fams
    }

    /// en: Resolve a live `chip_id` (AttachChip response) to a SKU. Silicon-revision bits [7:4] are
    /// masked out. Fail-closed: an ambiguous multi-family match returns `Unknown` rather than a
    /// guess; a same-family ambiguity returns `Family` with the candidates.
    /// ja: 実機の `chip_id` を SKU へ解決。rev [7:4] は無視。多 family で曖昧なら推測せず `Unknown`、
    /// 同 family の曖昧は候補付き `Family` を返す(fail-closed)。
    pub fn resolve_by_chip_id(&self, chip_id: u32) -> Resolution<'_> {
        let masked = chip_id & DEVICE_ID_MASK;
        let hits: Vec<&SkuRecord> = self
            .skus
            .iter()
            .filter(|s| s.device_id.map(|d| d & DEVICE_ID_MASK) == Some(masked))
            .collect();
        match hits.as_slice() {
            [] => Resolution::Unknown,
            [one] => Resolution::Sku(one),
            many => {
                let fam = &many[0].family;
                if many.iter().all(|s| &s.family == fam) {
                    Resolution::Family(fam.clone(), hits)
                } else {
                    Resolution::Unknown
                }
            }
        }
    }
}

/// One SKU record. Column meanings: docs/architecture.ja.md §3.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SkuRecord {
    pub sku: String,
    pub family: String,
    /// Part-number series (keys debug wiring); may be narrower than `family`.
    pub series: String,
    /// device_id read from memory (from measured evidence).
    pub device_id: Option<u32>,
    pub flash_bytes: u64,
    pub sram_bytes: u64,
    /// en: Verified on real silicon (kept distinct from merely "implemented").
    /// ja: 実機確認済みか(「実装済み」と区別する)。
    pub verified: bool,
    /// en: Comes from the provisional overlay (request to ch32-device-data pending).
    /// ja: 暫定 overlay 由来か(ch32-device-data へ依頼中)。
    pub provisional: bool,
}

#[cfg(test)]
mod tests {
    #![allow(clippy::panic, clippy::expect_used)]
    use super::*;

    #[test]
    fn builtin_db_is_non_empty() {
        assert!(Db::builtin().skus().len() > 20);
    }

    #[test]
    fn provenance_has_rev_and_fingerprint() {
        let p = provenance();
        // The generated headers carry `# source: ch32-device-data@<rev>`, so the rev must parse to a
        // non-empty token with no leftover header punctuation.
        let rev = p
            .source_rev
            .expect("source rev parsed from the generated header");
        assert!(!rev.is_empty());
        assert!(!rev.contains(' ') && !rev.contains('(') && !rev.contains('@'));
        // Same fingerprint convention as flash_stub_digest, and stable across calls.
        assert!(p.digest.starts_with("fnv1a64:"));
        assert_eq!(p.digest.len(), "fnv1a64:".len() + 16);
        assert_eq!(provenance().digest, p.digest);
    }

    #[test]
    fn resolves_measured_boards_with_rev_masked() {
        let db = Db::builtin();
        // Live chip_ids measured on real silicon; the rev nibble [7:4] differs from the datasheet
        // row for L103/V307 yet still resolves because [7:4] is masked out.
        let cases = [
            (0x1031_0710_u32, "CH32L103C8T6"), // datasheet 0x10310700
            (0x3070_0528, "CH32V307VCT6"),     // datasheet 0x30700508
            (0x2031_0500, "CH32V203C8T6"),
            (0x0351_0601, "CH32X035C8T6"),
            (0x0030_0500, "CH32V003F4P6"),
            (0x2500_410f, "CH32V103R8T6"),
        ];
        for (id, want) in cases {
            match db.resolve_by_chip_id(id) {
                Resolution::Sku(s) => assert_eq!(s.sku, want, "chip_id 0x{id:08x}"),
                other => panic!("chip_id 0x{id:08x} -> {other:?}, want {want}"),
            }
        }
    }

    #[test]
    fn unknown_chip_id_is_unknown() {
        assert_eq!(
            Db::builtin().resolve_by_chip_id(0xDEAD_BEEF),
            Resolution::Unknown
        );
    }

    #[test]
    fn option_user_fields_decode_l103() {
        let f = option_user_fields("CH32L103");
        // L103's RM names bit5 CFGCANM (family-specific) plus the common bits, high bit first.
        assert!(f.iter().any(|x| x.field == "CFGCANM" && x.bit == 5));
        assert!(f.iter().any(|x| x.field == "IWDGSW" && x.bit == 0));
        assert!(f.windows(2).all(|w| w[0].bit > w[1].bit));
    }

    #[test]
    fn option_user_fields_unknown_family_is_empty() {
        assert!(option_user_fields("CH32NOPE").is_empty());
    }

    #[test]
    fn families_for_chip_name_matches_sku_family_series_prefix() {
        let db = Db::builtin();
        // Exact SKU, family, series, and part-number prefix all resolve to the same family.
        assert_eq!(db.families_for_chip_name("CH32L103C8T6"), vec!["CH32L103"]);
        assert_eq!(db.families_for_chip_name("CH32L103"), vec!["CH32L103"]);
        assert_eq!(db.families_for_chip_name("ch32l103c8t6"), vec!["CH32L103"]); // case-insensitive
        // A different family does not appear.
        let v307 = db.families_for_chip_name("CH32V307VCT6");
        assert_eq!(v307, vec!["CH32V307"]);
        assert!(!v307.iter().any(|f| f == "CH32L103"));
        // Unknown name -> empty (callers must not treat as a conflict).
        assert!(db.families_for_chip_name("CH32V999ZZ").is_empty());
    }

    #[test]
    fn debug_wiring_1wire_vs_2wire() {
        // CH32V003 has only a single SWIO pad (1-wire); L103 has SWDIO+SWCLK (2-wire).
        let v003 = debug_wiring("CH32V003").expect("V003 wiring");
        assert_eq!(v003.wire, "1-wire");
        assert_eq!(v003.swclk, "-");
        let l103 = debug_wiring("CH32L103").expect("L103 wiring");
        assert_eq!(l103.wire, "2-wire");
        assert_eq!(l103.swdio, "PA13");
        assert!(debug_wiring("CH32NOPE").is_none());
    }
}
